import{_ as n}from"./peer-result-loop-a6370db4.js";import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as d,o as i,c as r,d as s,e,b as o,w as c,a as l,f as p}from"./app-0802a302.js";const u={},h=s("strong",null,"发出去的消息，结果怎么回到发起方？",-1),m=s("p",null,"这一篇记录最后的方案——异步回传——以及一路上修掉的几个真 bug。它们不“高级”，但每一个都能让整条链路看起来“完全没通”。",-1),b=p('<h2 id="_1-最终形态" tabindex="-1"><a class="header-anchor" href="#_1-最终形态" aria-hidden="true">#</a> 1. 最终形态</h2><figure><img src="'+n+`" alt="异步结果回传" tabindex="0" loading="lazy"><figcaption>异步结果回传</figcaption></figure><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>macmini: peer_send / peer_reply（可带 targetSessionId）
  → 立刻结束本轮（system prompt 规定，不要轮询）
hub: 投递到 hub 自有会话（Peer Inbox）
  → 跑一轮
  → turn/end 取最终 assistant 文本
  → session/state 查远端状态
  → running 用 steer / idle 用 prompt
  → [hub] &lt;文本&gt; 推回 macmini 的发起会话
macmini: 收到 [hub] ... → 继续下一轮
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>没有同步阻塞，没有轮询，也没有“hub 的 agent 记得回复”这种人为依赖。</p><h2 id="_2-归属边界-hub-写不进-gui-会话" tabindex="-1"><a class="header-anchor" href="#_2-归属边界-hub-写不进-gui-会话" aria-hidden="true">#</a> 2. 归属边界：hub 写不进 GUI 会话</h2><p>这是最反直觉的一条。DSH 里 agent 有归属：</p><ul><li>GUI 会话的 agent 由 GUI 的会话控制器创建和持有</li><li>peer 插件 <code>agents.get(那个 id)</code> 返回空，<code>resume</code> 也会失败</li></ul><p>所以“把消息投到用户正在看的会话”在插件层面做不到。最终方案是 hub <strong>自己建一个会话</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>会话 id: peer-inbox（或 peer-inbox-xxxx）
归属:    hub 插件
可见:    挂到 workspace，GUI 里能看到
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>peer 消息默认投到这里，它的 agent 起一轮处理，结果再推回 macmini。等于给 peer 通信开了一个“收发室”。</p><h2 id="_3-steer-还是-prompt" tabindex="-1"><a class="header-anchor" href="#_3-steer-还是-prompt" aria-hidden="true">#</a> 3. steer 还是 prompt</h2><p>回传时 macmini 可能在跑，也可能空闲：</p><table><thead><tr><th>远端状态</th><th>方式</th><th>效果</th></tr></thead><tbody><tr><td>running</td><td><code>session/steer</code></td><td>插进当前轮的下一个 step，轮询立刻停</td></tr><tr><td>idle</td><td><code>session/prompt</code></td><td>起一轮，<code>[hub]</code> 作为新一轮输入</td></tr></tbody></table><p>状态不能信缓存（<code>session.status</code> 通知我们从来没收到过），所以回传前直接查：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token keyword">await</span> link<span class="token punctuation">.</span>conn<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;session/state&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> sessionId <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token keyword">const</span> running <span class="token operator">=</span> state<span class="token operator">?.</span>status <span class="token operator">!==</span> <span class="token string">&#39;idle&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-本次修掉的真-bug" tabindex="-1"><a class="header-anchor" href="#_4-本次修掉的真-bug" aria-hidden="true">#</a> 4. 本次修掉的真 bug</h2><table><thead><tr><th>现象</th><th>根因</th><th>修复</th></tr></thead><tbody><tr><td>macmini 永远收不到结果</td><td><code>#deliverToAgent</code> 里 <code>const sessionId = agent.session.id</code> <strong>覆盖了参数</strong>，<code>remoteSessionId</code> 记成本地 id</td><td>本地 id 只作 map key，<code>remoteSessionId</code> 保留远端 id</td></tr><tr><td>新建会话报 <code>unknown peer session</code></td><td>会话还没创建就调 <code>working-directory/set</code></td><td>忽略该错误；新会话 cwd 由 <code>peer/prepare-session</code> 在创建时带上</td></tr><tr><td>hub 找不到 agent，消息落 pending</td><td>归属隔离，GUI 会话不可写</td><td>投递到 hub 自有的 Peer Inbox</td></tr><tr><td>回传总走 prompt、排队</td><td>缓存的 <code>session.status</code> 永远是 idle</td><td>回传前查 <code>session/state</code></td></tr><tr><td>忙碌会话等到整轮结束</td><td><code>followup</code> 只能等</td><td>running 时改 <code>steer</code></td></tr></tbody></table><p>第一个 bug 最典型：它不报错、不影响投递，只是<strong>回传发到了不存在的会话</strong>。表现就是“消息明明进了会话，对面就是收不到”。</p><h2 id="_5-怎么验证" tabindex="-1"><a class="header-anchor" href="#_5-怎么验证" aria-hidden="true">#</a> 5. 怎么验证</h2><p>不要靠“看起来应该通了”，要留下证据：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>~/.dsh/peer-push.log
2026-11-07T16:16:42.002Z pushed prompt peer-macmini-fix1 bytes=46
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>macmini 端实际收到的内容：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>[hub] 收到，已忽略。

（hub 已完成这一轮，直接继续即可，不需要轮询。）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一边是推送日志，一边是接收原文，才算闭环。</p><h2 id="_6-发起方选择的代价" tabindex="-1"><a class="header-anchor" href="#_6-发起方选择的代价" aria-hidden="true">#</a> 6. 发起方选择的代价</h2><p>“谁发起谁选目标”是上一轮定下的方向：</p><ul><li>link 发送前用 <code>userQuestions.ask</code> 问用户选 hub 会话</li><li>不带 <code>targetSessionId</code> 就会弹卡片；没人点，发送会被取消</li></ul><p>这很符合“谁发起谁确认”，但在无人值守时就是阻塞。折中：</p><ul><li>常用目标（如 <code>peer-inbox</code>）设默认，减少弹卡</li><li>或者把选择结果记住，下一次复用</li></ul><h2 id="_7-被删掉的东西" tabindex="-1"><a class="header-anchor" href="#_7-被删掉的东西" aria-hidden="true">#</a> 7. 被删掉的东西</h2><p>中途实现过 <code>peer_ask_hub</code>：发送并同步等待 hub 这一轮的文本。它和异步回传重复，而且：</p><ul><li>阻塞调用方</li><li>hub 会话忙时会一直等</li><li>存在互等（hub 反过来同步调 link）</li></ul><p>最后删掉，只保留异步。<strong>能异步就不要同步</strong>——这是这次最实用的一条。</p><h2 id="_8-教训" tabindex="-1"><a class="header-anchor" href="#_8-教训" aria-hidden="true">#</a> 8. 教训</h2><ul><li><strong>归属边界先搞清楚</strong>：不是所有会话都能写，插件只能写自己拥有的</li><li><strong>回传的 id 必须是远端的</strong>：本地 id 和远端 id 同名变量是灾难</li><li><strong>状态不要信缓存</strong>：查一次 <code>session/state</code> 比维护通知可靠</li><li><strong>部署后确认进程真的重启了</strong>：我遇到过定时重启没生效、在旧进程上测了半天</li><li><strong>日志先行</strong>：<code>peer-push.log</code> 一加，问题立刻从“玄学”变成“一行失败信息”</li></ul>`,35);function g(v,_){const t=d("RouterLink");return i(),r("div",null,[s("p",null,[e("上一篇做了"),o(t,{to:"/architecture/dsh-peer-selection.html"},{default:c(()=>[e("会话选择")]),_:1}),e("。选完之后真正的问题才浮出来："),h]),m,l(" more "),b])}const y=a(u,[["render",g],["__file","dsh-peer-result-push.html.vue"]]);export{y as default};
